// The chat's replies as work: what Send, Stop, Try again and Edit do, and
// what the view is told about each reply. The view (chat.tsx) draws what
// this says and calls these; it writes nothing itself.
//
// A reply is generated by generate-task.js, asked with doWork under the
// reply's key (reply.js): on the person's own queue when one of their
// machines serves it, so it goes on when this page closes and every page of
// theirs sees it; otherwise in this page. Every reply that has not ended is
// followed by its key (watchWork), so a reply being written on the person's
// queue, asked from another tab or before a reload, is shown as going on,
// with Stop, and nothing is sent into the chat meanwhile. What each reply
// shows is decided in reply-status.js from the reply and that work.

import { updateText } from '@automerge/automerge-repo';
import { doWork, inSamePackage, stopWork, watchWork } from './task-client.js';
import { needsOf, replyAsk, replyKey, requestFor } from './reply.js';
import { shownReply, underWay } from './reply-status.js';

// Vite sets this in the built package, whose task is dist/generate-task.js (vite.config.ts)
const BUILT = /** @type {any} */ (import.meta).env?.PROD === true;

/**
 * Where the reply's code is, as an import url both this page and a pool can
 * import: the package's own file, named by the package's url and not this
 * site's, when this module was loaded from a package in automerge; otherwise
 * the file of this build or source beside this module, which only this page
 * can import, so the work is done here.
 */
export function generateTaskUrl(here = import.meta.url, built = BUILT) {
  const inPackage = inSamePackage(here, built ? 'dist/generate-task.js' : 'src/generate-task.js');
  // the built module is in dist/assets/, the task in dist/
  return inPackage ?? new URL(built ? '../generate-task.js' : './generate-task.js', here).href;
}

/**
 * Follows a chat's replies and does what the person asks of them.
 * @param {any} handle  the chat's handle
 * @param {any} repo  the page's Repo
 * @param {{ apiKey: string, importUrl?: string, onChange?: () => void }} options
 */
export function chatReplies(handle, repo, { apiKey, importUrl = generateTaskUrl(), onChange }) {
  let dead = false;
  /** this page's own work, by reply id: the latest asking, kept once it has ended @type {Map<string, { controller: AbortController, view: any }>} */
  const own = new Map();
  /** the work under each unended reply's key, as watchWork has it; its view undefined until it first reports @type {Map<string, { view: any, stop: () => void }>} */
  const seen = new Map();
  const changed = () => {
    if (!dead) onChange?.();
  };

  const messages = () => /** @type {any[]} */ ([...(handle.doc()?.messages ?? [])]);
  const byId = (/** @type {string} */ id) => messages().find((m) => m?.id === id);

  /**
   * The work going on now for a reply (reply-status.js's Work): this page's
   * own, or the one followed on the queue; null when none is, and undefined
   * while the queue has not yet said. Work that is over is never returned,
   * because what it did is in the message.
   */
  function work(/** @type {any} */ message) {
    const mine = own.get(message.id)?.view;
    if (mine && underWay(mine.state)) return mine;
    // an ended reply is not followed (follow), so only this page's own work could be going on for it
    if (message.ended) return null;
    const followed = seen.get(message.id);
    if (!followed || followed.view === undefined) return undefined;
    return underWay(followed.view.state) ? followed.view : null;
  }

  /** What is shown of a message: null for one that is not a reply this tool can follow. */
  const shown = (/** @type {any} */ message) => (message?.role === 'assistant' && typeof message.id === 'string' ? shownReply(message, work(message)) : null);

  const beingWritten = (/** @type {string} */ id) => {
    const status = shown(byId(id))?.status;
    return status === 'streaming' || status === 'looking';
  };

  /** Whether a reply in the chat is being written, or may be: then nothing is sent into it. */
  const busy = () => messages().some((m) => {
    const status = shown(m)?.status;
    return status === 'streaming' || status === 'looking';
  });

  /** Follows the key of every reply that has not ended, and lets go of the rest. */
  function follow() {
    if (dead) return;
    const open = new Set(messages().filter((m) => m?.role === 'assistant' && typeof m.id === 'string' && !m.ended).map((m) => m.id));
    for (const [id, followed] of seen) {
      if (!open.has(id)) {
        followed.stop();
        seen.delete(id);
      }
    }
    for (const id of open) {
      if (seen.has(id)) continue;
      const followed = { view: /** @type {any} */ (undefined), stop: () => {} };
      seen.set(id, followed);
      followed.stop = watchWork(repo, replyKey(handle.url, id), (view) => {
        if (dead || seen.get(id) !== followed) return;
        followed.view = view;
        changed();
      });
    }
  }

  /** Has the reply with this id written by the work, asked under its key. */
  async function start(/** @type {string} */ id) {
    const controller = new AbortController();
    const mine = { controller, view: /** @type {any} */ ({ state: 'starting', taskUrl: null }) };
    own.set(id, mine);
    changed();
    const { input, key } = replyAsk(handle.url, id, requestFor(handle.doc(), id, beingWritten), apiKey);
    const needs = needsOf(handle.doc());
    let how = 'failed';
    try {
      await doWork(repo, { importUrl, input, key, ...(needs ? { needs } : {}) }, {
        signal: controller.signal,
        onProgress: (view) => {
          if (own.get(id) !== mine) return;
          mine.view = view;
          changed();
        },
      });
      how = 'succeeded';
    } catch {
      // how it went is in the message, if the run wrote it; the work is over either way
      how = controller.signal.aborted ? 'cancelled' : 'failed';
    } finally {
      // over, however the views left it, so that it no longer counts as going on
      if (underWay(mine.view.state)) mine.view = { ...mine.view, state: how };
      changed();
    }
  }

  /**
   * Sends the person's message: it and an empty reply go into the chat in
   * one change, then the reply is asked for. Nothing is sent while a reply
   * is being written. Returns the reply's id, or null when nothing was sent.
   */
  function send(/** @type {string} */ text) {
    const content = text.trim();
    if (dead || !content || busy()) return null;
    const replyId = crypto.randomUUID();
    handle.change((/** @type {any} */ d) => {
      d.messages.push({ id: crypto.randomUUID(), role: 'user', content });
      d.messages.push({ id: replyId, role: 'assistant', content: '' });
    });
    follow();
    void start(replyId);
    return replyId;
  }

  /** Stops the reply's work: this page's own by its signal, work seen on the queue by its key. */
  function stop(/** @type {string} */ id) {
    const message = byId(id);
    if (!message) return;
    const w = work(message);
    if (!w || !underWay(w.state)) return;
    const mine = own.get(id);
    if (mine && mine.view === w) mine.controller.abort();
    else void stopWork(repo, replyKey(handle.url, id));
  }

  /**
   * Asks again, under the same key, for a reply that did not finish and is
   * not being written. The reply is first put back as Send made it (its id,
   * its role, no text), in one change, because a run does nothing to a reply
   * that has ended.
   */
  function tryAgain(/** @type {string} */ id) {
    const message = byId(id);
    if (!shown(message)?.retry) return;
    handle.change((/** @type {any} */ d) => {
      const i = d.messages.findIndex((/** @type {any} */ m) => m?.id === id);
      if (i >= 0) d.messages[i] = { id, role: message.role, content: '' };
    });
    void start(id);
  }

  /**
   * Puts the person's edit into the reply, once its work has ended. `at` is
   * the chat's heads when the editor was opened (opened()), and the edit is
   * made as of then: it changes the text the person saw, in the message they
   * saw. Text written into that message since stays beside the edit, and a
   * message another run has put in the reply's place since is left whole, as
   * every other write to a message that was replaced is.
   */
  function edit(/** @type {string} */ id, /** @type {string} */ text, /** @type {any} */ at = handle.heads()) {
    if (!shown(byId(id))?.editable) return false;
    handle.changeAt(at, (/** @type {any} */ d) => {
      const i = d.messages.findIndex((/** @type {any} */ m) => m?.id === id);
      if (i >= 0) updateText(d, ['messages', i, 'content'], text);
    });
    return true;
  }

  const update = () => {
    follow();
    changed();
  };
  handle.on('change', update);
  follow();

  return {
    shown,
    busy,
    send,
    stop,
    tryAgain,
    edit,
    /** What an editor opened now starts from: the reply's text, and the chat's heads it was read at (edit's `at`). */
    opened: (/** @type {string} */ id) => ({ text: String(byId(id)?.content ?? ''), at: handle.heads() }),
    dispose() {
      dead = true;
      handle.off('change', update);
      // work done in this page ends with it; work on the person's queue goes on
      for (const { controller, view } of own.values()) {
        if (underWay(view.state) && !view.taskUrl) controller.abort();
      }
      for (const { stop } of seen.values()) stop();
      seen.clear();
    },
  };
}
